#include <Servo.h>
#include <SPI.h>
#include <MFRC522.h>

#define SS_PIN 10
#define RST_PIN 9
#define BUZZER_PIN 5
#define SERVO_PIN 6

MFRC522 mfrc522(SS_PIN, RST_PIN);
Servo servo;

unsigned long uidDec;                            // karta UID raqami (o'nlik)
const unsigned long RUXSAT_UID = 3840107306UL;   // 2-variant: ruxsat berilgan karta

void setup() {
  Serial.begin(9600);
  Serial.println("Karta kutilmoqda...");
  SPI.begin();             // SPI shinasini ishga tushirish
  mfrc522.PCD_Init();      // MFRC522 modulini ishga tushirish
  servo.attach(SERVO_PIN);
  servo.write(0);          // qulf yopiq holatda
}

void loop() {
  // Yangi karta bormi?
  if (!mfrc522.PICC_IsNewCardPresent()) {
    return;
  }
  // Kartaning UID sini o'qish
  if (!mfrc522.PICC_ReadCardSerial()) {
    return;
  }

  // UID baytlarini bitta o'nlik songa aylantirish
  uidDec = 0;
  for (byte i = 0; i < mfrc522.uid.size; i++) {
    uidDec = uidDec * 256 + mfrc522.uid.uidByte[i];
  }
  Serial.print("Card UID: ");
  Serial.println(uidDec);

  if (uidDec == RUXSAT_UID) {
    Serial.println("Ruxsat berildi");
    tone(BUZZER_PIN, 200, 500);   // ochilish signali
    servo.write(90);              // qulf ochiladi
    delay(3000);                  // 3 soniya ochiq turadi
    tone(BUZZER_PIN, 500, 500);   // yopilish signali
    servo.write(0);               // qulf yopiladi
  } else {
    Serial.println("Ruxsat yo'q");
    tone(BUZZER_PIN, 100, 1000);  // rad etish signali
  }
  mfrc522.PICC_HaltA();           // kartani o'qishni to'xtatish
}
